\label{prop:restricted-local-information-v2}
For $h\in E$,
\[
\inf_{s\in T:\,B[s]=h}
\frac12\left\lVert s\right\rVert_{L^2(Q_0)}^2
=
\begin{cases}
\displaystyle \frac12h^\top C_T^\dagger h,&h\in S_T,\\[6pt]
+\infty,&h\notin S_T,
\end{cases}
\]
where $C_T^\dagger$ is the Moore--Penrose pseudoinverse.  In particular, the family has full first-order decision coverage, $B(T)=E$, if and only if $\operatorname{rank}(C_T)=\dim E$.

\label{prop:app-v2-exact-projection}
Under (I1)--(I5), for every $a$ sufficiently close to $a_0$,
\[
Q_a^*\in\arg\min_{Q\in\mathcal C_a}D_{\mathrm{KL}}(Q\|Q_0)
\]
and
\begin{equation}
\label{eq:app-v2-contracted-value}
I_{Q_0}(a)
=
-\Lambda(a,\lambda(a)).
\end{equation}
